package com.jbrempresa.backend.repository;import java.math.BigDecimal;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import com.jbrempresa.backend.entity.CajaMovimiento;
public interface CajaMovimientoRepository extends JpaRepository<CajaMovimiento,Long>{List<CajaMovimiento> findByEmpIdAndCasIdAndCamActTrueOrderByCamFecMovDesc(Long empId,Long sesionId);@Query("select coalesce(sum(case when m.camTip in ('ENTRADA','COBRO') then m.camImp else -m.camImp end),0) from CajaMovimiento m where m.empId=:emp and m.casId=:ses and m.camAct=true and m.camMed='EFECTIVO'")BigDecimal saldoEfectivo(@Param("emp")Long emp,@Param("ses")Long ses);}
